### Problem Description

Synthetic source construction fails for empty nested objects.

### Steps to Reproduce

```
PUT /my_index
{
  "mappings": {
    "_source": { "mode": "synthetic" },
    "properties": {
      "obj": {
        "type": "nested",
        "properties": {
          "k": {
              "type": "keyword"
          }
        }
      }
    }
  }
}

PUT my_index/_doc/1
{
  "obj": [{"k": "key1"}, {"k": null}]
}
```

```
GET /my_index/_doc/1
```

```
    "statusCode": 500,
    "body": {
        "error": {
            "root_cause": [
                {
                    "type": "json_generation_exception",
                    "reason": "Can not start an object, expecting field name (context: Object)"
                }
            ],
            "type": "json_generation_exception",
            "reason": "Can not start an object, expecting field name (context: Object)",
            "suppressed": [
                {
                    "type": "illegal_state_exception",
                    "reason": "Failed to close the XContentBuilder",
                    "caused_by": {
                        "type": "i_o_exception",
                        "reason": "Unclosed object or array found"
                    }
                }
            ]
        },
        "status": 500
    },
```

